import {beginnerDiagram,beginnerVisual} from './beginner-view.mjs';
import {atlasSchematic} from './electronics-atlas.mjs';
import {depthHtml} from './lesson-depth.mjs';
import {courseVideoTiming} from './course-video-timing.mjs';
import {foundationLessons,studyBlocks} from './study-plan-content.mjs';
import {units,videos} from './learning-content.mjs';
import {instrumentLessons} from './instrument-content.mjs';
import {circuits,circuitSvg} from './circuit-library.mjs';
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export const routeIds=studyBlocks.flatMap(b=>b.lessons);
export function resolveLesson(id){if(id.startsWith('u:'))return units.find(u=>u.id===id.slice(2));if(id.startsWith('i:'))return instrumentLessons.find(u=>u.id===id.slice(2));return foundationLessons.find(u=>u.id===id);}
export function routeCompleted(id,local,legacy,instruments){return id.startsWith('u:')?!!legacy[id.slice(2)]?.passed:id.startsWith('i:')?instruments.includes(id.slice(2)):!!local[id]?.passed;}
export function mountStudyPlan(api){
 const $=id=>document.getElementById(id),read=(k,d)=>{try{return JSON.parse(api.storage.getItem(k))||d;}catch{return d;}};
 let progress=read('circuitlab-plan-v11',{}),settings=read('circuitlab-study-pace',{sessions:3}),current='',phase=0,spoken=false,voiceToken=0;
 const host=document.createElement('section');host.id='studyPlan';$('coursePage').prepend(host);
 const modal=document.createElement('dialog');modal.id='planDialog';modal.className='planDialog';document.body.append(modal);
 const save=()=>{try{api.storage.setItem('circuitlab-plan-v11',JSON.stringify(progress));}catch{}};
 const completed=id=>routeCompleted(id,progress,read('circuitlab-studio-v7',{}),read('circuitlab-instruments-v8',[]));
 function stop(){modal.querySelector('video')?.pause();}
 modal.addEventListener('close',stop);modal.addEventListener('cancel',stop);
 function render(){const next=routeIds.find(id=>!completed(id))||routeIds[0],count=routeIds.filter(completed).length,bi=studyBlocks.findIndex(b=>b.lessons.includes(next));
 host.innerHTML=`<div class="planIntro"><span class="studioKicker">PLAN DE ESTUDIO · ${studyBlocks.length} BLOQUES · ${routeIds.length} LECCIONES</span><h1>Primero, una resistencia.<br><em>Después, paso a paso.</em></h1><p>Empieza por las piezas: resistencias → condensadores → bobinas → diodos → transistores → redes. Una idea y un ejercicio cada vez. Los cálculos y las averías vienen después.</p><div class="courseFacts"><span><b>${studyBlocks.length} bloques</b>De los fundamentos al diagnóstico</span><span><b>62 vídeos</b>Con voz y subtítulos</span><span><b>3 instrumentos</b>Un mismo banco de pruebas</span></div><div class="courseArtwork" aria-hidden="true"><svg viewBox="0 0 470 340"><defs><radialGradient id="labHalo"><stop stop-color="#46d9bd" stop-opacity=".18"/><stop offset="1" stop-color="#46d9bd" stop-opacity="0"/></radialGradient><linearGradient id="labBoard" x2="1" y2="1"><stop stop-color="#163648"/><stop offset="1" stop-color="#0b192d"/></linearGradient></defs><ellipse cx="235" cy="175" rx="230" ry="160" fill="url(#labHalo)"/><g transform="translate(40 28) rotate(-8 195 142)"><rect x="8" y="14" width="385" height="260" rx="24" fill="#020915" opacity=".4"/><rect width="385" height="260" rx="24" fill="url(#labBoard)" stroke="#427c86"/><g stroke="#377074" fill="none" stroke-width="2"><path d="M20 60H95L128 93H161M20 190H97L129 158H161M222 94H280L310 64H367M222 155H265L302 193H367M192 18V72M192 180V240"/><path d="M35 107H100L134 125H161M222 124H317V229M82 20V40H135V73" opacity=".5"/></g><g fill="#eab977"><circle cx="22" cy="60" r="5"/><circle cx="22" cy="190" r="5"/><circle cx="364" cy="64" r="5"/><circle cx="364" cy="193" r="5"/></g><rect x="148" y="77" width="89" height="104" rx="9" fill="#071525" stroke="#69d8c1"/><g stroke="#a7cfcd" stroke-width="4"><path d="M137 95H148M137 113H148M137 131H148M137 149H148M237 95H248M237 113H248M237 131H248M237 149H248"/></g><text x="192" y="122" text-anchor="middle" fill="#a9f7df" font-size="19" font-family="monospace">LAB</text><text x="192" y="147" text-anchor="middle" fill="#7a9baa" font-size="9" font-family="monospace">OBSERVA · MIDE</text><rect x="39" y="207" width="103" height="30" rx="7" fill="#112c3b" stroke="#41647a"/><path d="M47 223H60L66 213L74 231L82 216L91 223H132" fill="none" stroke="#78edcc" stroke-width="2"/><text x="273" y="229" fill="#7299aa" font-family="monospace" font-size="9">CIRCUITLAB / 01</text><g fill="#071323" stroke="#41647a"><circle cx="20" cy="20" r="5"/><circle cx="365" cy="20" r="5"/><circle cx="20" cy="240" r="5"/><circle cx="365" cy="240" r="5"/></g></g></svg></div></div><section class="planNext"><div><small>${count===routeIds.length?'RECORRIDO COMPLETADO · REPASO':'TU SIGUIENTE PASO'} · BLOQUE ${bi+1} / ${studyBlocks.length}</small><h2>${resolveLesson(next).title}</h2><p>${studyBlocks[bi].goal}</p><button id="planResume" class="academyPrimary">${count?'Continuar donde lo dejé':'Empezar poco a poco'} →</button></div><div class="planScore"><strong>${Math.round(count/routeIds.length*100)}%</strong><span>${count} / ${routeIds.length} lecciones</span><progress max="${routeIds.length}" value="${count}" aria-label="Progreso del plan"></progress><small>Progreso en este navegador</small></div></section><div class="planRhythm"><div><h3>Tu ritmo, sin prisas</h3><p>Empieza con una lección de unos 10 minutos. Lee la idea, mira el dibujo y haz el ejercicio. Avanza cuando puedas explicarlo con tus palabras; no necesitas terminar un bloque de golpe.</p></div><label>Sesiones por semana<select id="studyPace">${[2,3,5].map(n=>`<option value="${n}" ${settings.sessions===n?'selected':''}>${n} sesiones</option>`).join('')}</select></label><p><b>${Math.ceil((routeIds.length-count)/settings.sessions)} semanas</b> orientativas para una primera vuelta. La destreza necesita repetición y casos reales.</p></div><div class="planSequence"><span>01 Entender</span><span>02 Ver</span><span>03 Resolver</span><span>04 Practicar</span><span>05 Comprobar</span></div><h2>Tu itinerario</h2><p>Primera vuelta: bloques 1–6, una pieza cada vez. Segunda vuelta: magnitudes, medición y circuitos. Finalmente: diagnóstico y reparación. Sigue el botón de continuación para mantener el orden.</p>${studyBlocks.map((b,i)=>{const n=b.lessons.filter(completed).length;return `<details class="planBlock" ${i===bi?'open':''}><summary><span class="blockNumber">${String(i+1).padStart(2,'0')}</span><span><b>${b.title}</b><small>${n===b.lessons.length?'✓ Completado':i===bi?'→ Estás aquí':'Después'} · ${n}/${b.lessons.length} lecciones</small></span></summary><p>${b.goal}</p><div class="planLessons">${b.lessons.map(id=>`<button data-plan="${id}" class="${id===next?'next':''}" ${id===next?'aria-current="step"':''}><span>${completed(id)?'✓':String(routeIds.indexOf(id)+1).padStart(2,'0')}</span><div><b>${resolveLesson(id).title}</b><small>${id.startsWith('i:')?'Instrumento · configuración comprobada':id.startsWith('u:')?'Teoría + vídeo + práctica 3D comprobada':resolveLesson(id).beginner?'Inicio · 10 min · una idea + dibujo + ejercicio':'Concepto + vídeo + 2 ejemplos + ejercicio'}</small></div><span>→</span></button>`).join('')}</div><div class="blockCheckpoint"><b>Antes de avanzar debes poder…</b><p>${b.checkpoint}</p><button data-review="${b.lessons[0]}">Repasar este bloque</button></div></details>`;}).join('')}<details class="planVideoShelf"><summary>Videoteca ordenada · ${foundationLessons.filter(l=>l.video).length+videos.length} demostraciones</summary><p>50 microclases con voz sintética incorporada al archivo, más 12 vídeos anteriores con audio integrado.</p>${studyBlocks.map(b=>`<h3>${b.title}</h3><div class="planVideoGrid">${b.lessons.filter(id=>!id.includes(':')&&resolveLesson(id).video).map(id=>{const l=resolveLesson(id);return `<button data-film="${id}"><img src="videos/${l.video}.jpg" loading="lazy" alt=""><b>▶ ${l.title}</b><small>4 escenas · voz y subtítulos</small></button>`;}).join('')}</div>`).join('')}<button id="oldVideos">Ver los 12 vídeos del banco y los instrumentos</button></details><p class="planBoundary">La ruta prepara para el diagnóstico y la reparación. La soldadura, la seguridad y la validación sobre equipos reales requieren práctica supervisada. El progreso del simulador no certifica un nivel profesional.</p>`;
 $('planResume').onclick=()=>open(next);$('studyPace').onchange=e=>{settings.sessions=Number(e.target.value);try{api.storage.setItem('circuitlab-study-pace',JSON.stringify(settings));}catch{}render();};host.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>open(b.dataset.plan));host.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>open(b.dataset.review));host.querySelectorAll('[data-film]').forEach(b=>b.onclick=()=>open(b.dataset.film,1));$('oldVideos').onclick=()=>{const el=document.querySelector('#learningStudio .videoLibrary')?.closest('details');if(el){el.open=true;el.scrollIntoView({behavior:'smooth'});}};
 }
 function open(id,p){stop();current=id;if(id.startsWith('u:')){api.openUnit(id.slice(2));return;}if(id.startsWith('i:')){document.dispatchEvent(new CustomEvent('circuitlab:instruments',{detail:{lesson:id.slice(2)}}));return;}const l=resolveLesson(id),bi=studyBlocks.findIndex(b=>b.lessons.includes(id));phase=p??progress[id]?.phase??0;progress[id]={...progress[id],phase};save();const c=circuits.find(c=>c.id===l.pattern);const state=progress[id]||{};
 const panels=[`<section class="planConcept"><h3>Una idea cada vez</h3><p>${l.concept}</p>${l.beginner?'':depthHtml(l)}<figure>${l.beginner?beginnerDiagram(l):l.id==='zener-curso'?atlasSchematic('zener'):circuitSvg(c.kind)}<figcaption>${l.beginner?'Representación simplificada; no es un pinout físico.':`Circuito de referencia: ${l.id==='zener-curso'?'Zener con resistencia limitadora':c.name}. Esquema de principio; los ejemplos pueden usar otros valores.`}</figcaption></figure><aside><b>Evita esta confusión</b><p>${l.trap}</p></aside></section>`,l.beginner?beginnerVisual(l):`<h3>Mira, pausa y relaciona</h3><video id="planVideo" controls playsinline preload="metadata" poster="videos/${l.video}.jpg"><source src="videos/${l.video}.mp4?v=13" type="video/mp4"><track kind="subtitles" srclang="es" label="Castellano" default src="videos/${l.video}.vtt?v=13"></video><p>Voz sintética en castellano integrada en el vídeo. Texto, escenas y subtítulos siguen la duración de la narración.</p><button id="narratePlan">▶ Ver con voz</button> <button id="stopPlanVoice">Pausar vídeo</button><p id="planVoiceStatus" role="status"></p><div class="planChapterButtons">${['Idea','Ejemplo','Contraste','Precaución'].map((t,i)=>`<button data-chapter="${i}">${i+1}. ${t}</button>`).join('')}</div><details><summary>Leer transcripción</summary>${l.scenes.map(s=>`<p>${s}</p>`).join('')}</details>`,`<section class="planWorked"><span>EJEMPLO 1 · CASO RESUELTO</span><h3>Comprende el resultado</h3><p>${l.example}</p></section><section class="planWorked"><span>EJEMPLO 2 · CAMBIA UNA CONDICIÓN</span><h3>Compara y razona</h3><p>${l.contrast}</p></section><p>No memorices solo la cifra: identifica qué condición cambió y por qué modifica el resultado.</p>`,`<h3>Ahora hazlo tú</h3><p>${l.task}</p>${l.beginner?'':depthHtml(l,true)}<label>Tu razonamiento<textarea id="planNote" rows="6" placeholder="Datos, predicción, comprobación y conclusión…">${esc(state.note||'')}</textarea></label><p>Se guarda como ejercicio escrito de autoevaluación. Explica tu respuesta y compárala con los ejemplos; la longitud del texto no acredita que sea correcta.</p><button id="planCircuit">${l.beginner?'Opcional: ver un circuito que usa esta pieza →':'Consultar el circuito y su práctica relacionada →'}</button>`,`<h3>${l.question}</h3><div class="planAnswers">${l.answers.map((a,i)=>`<button data-plan-answer="${i}">${a}</button>`).join('')}</div><p id="planAnswerFeedback" role="status">${state.quiz?'✓ Comprensión comprobada.':'Elige una respuesta antes de finalizar.'}</p><p><b>Ejercicio escrito:</b> ${state.note?.trim()?'Guardado para autoevaluación.':'Pendiente: vuelve a Practicar y registra tu razonamiento.'}</p><button id="finishPlanLesson" class="academyPrimary" ${!state.quiz||!state.note?.trim()?'disabled':''}>He entendido esta idea · completar →</button>`];
 modal.innerHTML=`<div class="planDialogHead"><span>BLOQUE ${bi+1} · ${studyBlocks[bi].title}<br>LECCIÓN ${routeIds.indexOf(id)+1} / ${routeIds.length}</span><button id="closePlan" aria-label="Cerrar lección">×</button></div><h2>${l.title}</h2><nav class="planTabs" aria-label="Pasos de la lección">${['Entender',l.beginner?'Ver dibujo':'Ver vídeo','Ejemplos','Practicar','Comprobar'].map((s,i)=>`<button data-plan-phase="${i}" ${i===phase?'aria-current="step"':''}>${i+1}. ${s}</button>`).join('')}</nav><div class="planPanel">${panels[phase]}</div><div class="planFoot"><button id="planPrev">${phase?'← Anterior':'← Mi ruta'}</button><span>Paso ${phase+1} / 5</span><button id="planNextStep" ${phase===4?'hidden':''}>Siguiente →</button></div>`;
 if(!modal.open)modal.showModal();modal.scrollTop=0;document.dispatchEvent(new CustomEvent('circuitlab:lesson-open',{detail:{target:'planDialog',id,beginner:!!l.beginner}}));$('closePlan').onclick=()=>modal.close();modal.querySelectorAll('[data-plan-phase]').forEach(b=>b.onclick=()=>open(id,Number(b.dataset.planPhase)));$('planPrev').onclick=()=>phase?open(id,phase-1):modal.close();$('planNextStep').onclick=()=>open(id,Math.min(4,phase+1));$('planNote')?.addEventListener('input',e=>{progress[id]={...progress[id],note:e.target.value};save();});$('planCircuit')?.addEventListener('click',()=>{modal.close();api.openCircuit(l.pattern);});
 modal.querySelectorAll('[data-plan-answer]').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.planAnswer)===l.correct;progress[id]={...progress[id],quiz:ok};save();$('planAnswerFeedback').textContent=(ok?'✓ Correcto. ':'Revisa: ')+l.concept;$('finishPlanLesson').disabled=!ok||!progress[id]?.note?.trim();});$('finishPlanLesson')?.addEventListener('click',()=>{if(!progress[id]?.quiz||!progress[id]?.note?.trim())return;progress[id]={...progress[id],passed:true};save();modal.close();render();host.scrollIntoView({behavior:'smooth'});});
 if(phase===1&&l.video){const player=$('planVideo');modal.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>{player.currentTime=courseVideoTiming[l.video].starts[Number(b.dataset.chapter)];});$('stopPlanVoice').onclick=()=>player.pause();$('narratePlan').onclick=async()=>{player.muted=false;try{await player.play();$('planVoiceStatus').textContent='Reproduciendo imagen y voz integrada.';}catch{$('planVoiceStatus').textContent='Pulsa ▶ en el vídeo y comprueba el volumen del dispositivo.';}};}

 }
 document.addEventListener('circuitlab:progress',render);document.addEventListener('circuitlab:page',e=>{if(e.detail==='course')render();});
 document.getElementById('backToRoute')?.addEventListener('click',()=>host.scrollIntoView({behavior:'smooth'}));render();return {open,render};
}
